def populate_100_leads():
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    
    # Drop and recreate table with company_summary
    cur.execute("DROP TABLE IF EXISTS prospects")
    cur.execute("""
    CREATE TABLE prospects (
        lead_id TEXT PRIMARY KEY,
        company_name TEXT NOT NULL,
        company_summary TEXT,
        root_domain TEXT NOT NULL,
        headquarters TEXT,
        malaysia_facility TEXT,
        sector TEXT,
        estimated_transactions_mo TEXT,
        accounting_software TEXT,
        buyer_name TEXT,
        buyer_title TEXT,
        contact_email TEXT,
        contact_phone TEXT,
        sg_my_wedge TEXT,
        quality_score INTEGER,
        tier TEXT,
        status TEXT,
        notes TEXT
    )
    """)
    
    print(f"Populating {len(LEADS_100)} leads into {DB_PATH.name}...")
    for row in LEADS_100:
        cur.execute("""
        INSERT INTO prospects (
            lead_id, company_name, company_summary, root_domain, headquarters, malaysia_facility,
            sector, estimated_transactions_mo, accounting_software, buyer_name,
            buyer_title, contact_email, contact_phone, sg_my_wedge, quality_score,
            tier, status, notes
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, row)
        
    conn.commit()
    cur.execute("SELECT COUNT(*) FROM prospects")
    count = cur.fetchone()[0]
    conn.close()
    print(f"Total leads in database: {count}")
    
    # Sync to master_leads.xlsx
    sync_leads_to_master_excel()

if __name__ == "__main__":
    populate_100_leads()
